package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.introspect.AnnotationIntrospector;
import com.fasterxml.jackson.databind.jsonFormatVisitors.*;
import com.fasterxml.jackson.databind.ser.ContextualSerializer;
import com.fasterxml.jackson.databind.util.StdDateFormat;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.text.DateFormat;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DateTimeSerializerBase_createContextual_TriageGen0Test {

    private SerializerProvider serializers;
    private BeanProperty property;
    private AnnotationIntrospector annotationIntrospector;
    private TestDateTimeSerializer serializer;

    // Concrete implementation for testing abstract class
    private static class TestDateTimeSerializer extends DateTimeSerializerBase<java.util.Date> {
        private final Boolean useTimestamp;
        private final DateFormat customFormat;

        protected TestDateTimeSerializer(Boolean useTimestamp, DateFormat customFormat) {
            super(java.util.Date.class, useTimestamp, customFormat);
            this.useTimestamp = useTimestamp;
            this.customFormat = customFormat;
        }

        @Override
        public JsonSerializer<?> withFormat(Boolean timestamp, DateFormat format) {
            return new TestDateTimeSerializer(timestamp, format);
        }

        @Override
        public boolean isEmpty(java.util.Date value) { return value == null; }

        @Override
        public boolean isEmpty(SerializerProvider serializers, java.util.Date value) { return value == null; }

        @Override
        protected long _timestamp(java.util.Date value) { return value.getTime(); }

        @Override
        public void serialize(java.util.Date value, com.fasterxml.jackson.core.JsonGenerator gen, SerializerProvider serializers) throws java.io.IOException {
        }

        @Override
        public com.fasterxml.jackson.databind.JsonNode getSchema(SerializerProvider serializers, com.fasterxml.jackson.databind.JavaType typeHint) {
            return null;
        }

        @Override
        public void acceptJsonFormatVisitor(com.fasterxml.jackson.databind.ser.std.JsonFormatVisitorWrapper visitor, com.fasterxml.jackson.databind.JavaType typeHint) throws JsonMappingException {
        }
    }

    @Before
    public void setUp() {
        serializers = mock(SerializerProvider.class);
        property = mock(BeanProperty.class);
        annotationIntrospector = mock(AnnotationIntrospector.class);
        when(serializers.getAnnotationIntrospector()).thenReturn(annotationIntrospector);
        serializer = new TestDateTimeSerializer(false, null);
    }

    @Test
    public void testCreateContextual_PropertyIsNull() throws JsonMappingException {
        JsonSerializer<?> result = serializer.createContextual(serializers, null);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NoFormatFound() throws JsonMappingException {
        Annotated member = mock(Annotated.class);
        when(property.getMember()).thenReturn(member);
        when(annotationIntrospector.findFormat(member)).thenReturn(null);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }

    @Test
    public void testCreateContextual_NumericShape() throws JsonMappingException {
        Annotated member = mock(Annotated.class);
        when(property.getMember()).thenReturn(member);

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.NUMBER_INT);
        when(annotationIntrospector.findFormat(member)).thenReturn(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertTrue(result instanceof TestDateTimeSerializer);
        TestDateTimeSerializer tsResult = (TestDateTimeSerializer) result;
        // In the code: return withFormat(Boolean.TRUE, null);
        // We check if it's a new instance where useTimestamp is true
        // Note: we can't access private fields easily, but we can verify via behavior if needed. 
        // Here we rely on the fact that withFormat returns a new instance.
        assertNotSame(serializer, tsResult);
    }

    @Test
    public void testCreateContextual_StringShape_WithAllParams() throws JsonMappingException {
        Annotated member = mock(Annotated.class);
        when(property.getMember()).thenReturn(member);

        TimeZone tz = TimeZone.getTimeZone("GMT");
        Locale loc = Locale.US;
        String pattern = "yyyy-MM-dd";

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(true);
        when(format.getPattern()).thenReturn(pattern);
        when(format.hasLocale()).thenReturn(true);
        when(format.getLocale()).thenReturn(loc);
        when(format.getTimeZone()).thenReturn(tz);
        when(annotationIntrospector.findFormat(member)).thenReturn(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertTrue(result instanceof TestDateTimeSerializer);
        TestDateTimeSerializer tsResult = (TestDateTimeSerializer) result;
        assertNotSame(serializer, tsResult);
        // Since we can't easily assert the private DateFormat inside the result without reflection, 
        // the successful execution of the branch is the primary goal.
    }

    @Test
    public void testCreateContextual_StringShape_WithDefaults() throws JsonMappingException {
        Annotated member = mock(Annotated.class);
        when(property.getMember()).thenReturn(member);

        TimeZone defaultTz = TimeZone.getTimeZone("UTC");
        Locale defaultLoc = Locale.ENGLISH;
        when(serializers.getLocale()).thenReturn(defaultLoc);
        when(serializers.getTimeZone()).thenReturn(defaultTz);

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.STRING);
        when(format.hasPattern()).thenReturn(false);
        when(format.hasLocale()).thenReturn(false);
        when(format.getTimeZone()).thenReturn(null);
        when(annotationIntrospector.findFormat(member)).thenReturn(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);

        assertTrue(result instanceof TestDateTimeSerializer);
        assertNotSame(serializer, result);
    }

    @Test
    public void testCreateContextual_StringShape_NonNumericNonStringShape() throws JsonMappingException {
        // Testing the branch where shape is not numeric and not STRING
        Annotated member = mock(Annotated.class);
        when(property.getMember()).thenReturn(member);

        JsonFormat.Value format = mock(JsonFormat.Value.class);
        when(format.getShape()).thenReturn(JsonFormat.Shape.OBJECT); 
        when(annotationIntrospector.findFormat(member)).thenReturn(format);

        JsonSerializer<?> result = serializer.createContextual(serializers, property);
        assertSame(serializer, result);
    }
}
